import json, re, difflib, glob, pdfplumber
m=json.load(open('evals/dataset/manifest.json'))
def sents(t): return [s.strip() for s in re.split(r'(?<=[.!?:])\s+', re.sub(r'\s+',' ',t)) if len(s.strip())>=30]
new=[];old=[]
for e in m['entries']:
    if e['photo']: continue
    with pdfplumber.open('evals/dataset/'+e['file']) as pdf:
        t=" ".join(p.extract_text() or "" for p in pdf.pages)
    (new if e['split']=='newkinds' else old).extend(sents(t))
law=[]
for p in glob.glob('evals/law/*.txt'): law+=sents(open(p).read())
oldset=list(set(old)); lawset=list(set(law))
worst=[]
for s in set(new):
    best=(0,'')
    for o in oldset+lawset:
        if abs(len(o)-len(s))>0.5*len(s): continue
        r=difflib.SequenceMatcher(None,s,o).quick_ratio()
        if r>best[0]-0.0 and r>0.7:
            r=difflib.SequenceMatcher(None,s,o).ratio()
            if r>best[0]: best=(r,o)
    if best[0]>0.6: worst.append((best[0],s,best[1]))
for r,s,o in sorted(worst,reverse=True)[:12]: print(round(r,3),'|',s,'\n      ~',o)
print(len(set(new)),'sentences')
